// FAP §9: produce a result for the dispatcher's fn_build_response to wrap.
// data.serverTs lets the smoke-uibuilder-ping.mjs test measure roundtrip
// latency. _socketId is preserved automatically by Node-RED for routing back
// to the requesting client through merge-session-send.
msg._result = {
    ok: true,
    data: { pong: true, serverTs: Date.now() }
};
return msg;
